input.sparql:
PREFIX brick: <http://w3.org/ns/brick>
PREFIX ref: <http://purl.org/linked-data/dw./>
SELECT ?s ?class ?t ?tsid ?r
WHERE {
  ?s rdf:type brick:Zone .
  ?s brick:hasPoint ?p .
  ?p rdf:type ?class .
  OPTIONAL { ?p ref:hasExternalReference ?r . ?r ref:hasTimeseriesId ?tsid . }
}

SELECT ?zone ?zlabel ?point ?ptype WHERE {
  ?zone rdf:type <https://brickschema.org/schema/Brick#Zone> ; rdfs:label ?zlabel .
  ?zone <https://brickschema.org/schema/Brick#hasPoint> ?point .
  ?point rdf:type ?ptype .
} ORDER BY ?zlabel

SELECT ?point ?ptype ?tsid WHERE {
  ?point rdf:type <https://brickschema.org/schema/Brick#Air_Temperature_Sensor> .
  OPTIONAL { ?point <http://purl.org/linked-data/dw./hasExternalReference> ?r . ?r <http://purl.org/linked-data/dw./hasTimeseriesId> ?tsid . }
} ORDER BY ?point
